import {WINDOW} from '@ng-web-apis/common';
import {TuiRectAccessor} from '@taiga-ui/core/abstract';

export const TUI_VIEWPORT = new InjectionToken<TuiRectAccessor>(
    `[TUI_VIEWPORT]: Viewport accessor`,
