                    return {
                        top: 0,
                        left: 0,
                        right: windowRef.innerWidth,
                        bottom: windowRef.innerHeight,
                        width: windowRef.innerWidth,
                        height: windowRef.innerHeight,
                    };
                },
            };
        },
    },
);

export function tuiAsViewport(useExisting: Type<TuiRectAccessor>): Provider {
    return {
        provide: TUI_VIEWPORT,
        useExisting,
    };
}

