module.exports = {
    extends: ['@commitlint/config-conventional'],
    rules: {
        'scope-enum': () => {
            const {readdirSync, statSync} = require('fs');
            const dir = 'projects';
            const projectsNames = readdirSync(dir).filter(entity =>
                statSync(`${dir}/${entity}`).isDirectory(),
            );

            return [2, 'always', projectsNames];
        },
        'type-enum': () => {
            const [level, applicable, types] = require('@commitlint/config-conventional')
                .rules['type-enum'];

            return [level, applicable, [...types, 'deprecate']];
        },
    },
};

const base = require('@tinkoff/prettier-config/angular');

module.exports = {
    ...base,
    singleAttributePerLine: true,
    overrides: [
        ...base.overrides,
        {
            files: ['*.js', '*.ts'],
            options: {printWidth: 90, parser: 'typescript'},
        },
        {
            files: ['*.html'],
            options: {printWidth: 120, parser: 'angular'},
        },
    ],
};

module.exports = {
    extends: ['@tinkoff/stylelint-config/angular-less'],
    ignoreFiles: ['**/demo/**', '**/dist/**', '**/coverage/**', '**/node_modules/**'],
    rules: {
        'function-url-quotes': null,
        'selector-class-pattern': '^(_.*)|(t-.*)|(tui-.*)|(ng-.*)|(hljs.*)$',
        'unit-allowed-list': [
            'px',
            'rem',
            'em',
            'deg',
            's',
            'ms',
            'dpcm',
            'turn',
            'ch',
            '%',
            // 'vw/vh' have a big problem in Safari, when developers set viewport=width~1280px in Application
        ],
    },
};
